export const getCreateStatementPaymentSessionUrl = () => {




  return `/api/billing/payment-sessions`
}

/**
 * Atomically records the monetary amount received and/or consumes existing
 * customer credit. Credit is applied to its originating open invoice first,
 * then oldest eligible account invoices, and never posts to Undeposited
 * Funds. An unapplied monetary remainder becomes customer account credit.
 * Reusing an idempotencyKey returns the original matching session.
 *
 * Supplying statementId keeps the statement-led flow: monetary
 * applications are limited to invoices on sent statements. Omitting it
 * receives payment directly against the account's eligible outstanding
 * invoices, with no statement required.
 * @summary Record one customer payment, statement-led or invoice-led
 */
