export const getGetSharedProviderAccountUrl = (params: GetSharedProviderAccountParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/organizations/shared-accounts?${stringifiedParams}` : `/api/organizations/shared-accounts`
}

