export const getDownloadLabAutopayAuthorizationUrl = (id: string,
    params: DownloadLabAutopayAuthorizationParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/provider/lab-autopay-authorization/${id}/download?${stringifiedParams}` : `/api/provider/lab-autopay-authorization/${id}/download`
}

